7:function modBigInt(text, modulus) {
8:  const m = BigInt(modulus);
9:  let value = BigInt(text) % m;
10:  if (value < 0n) value += m;
11:  return Number(value);
12:}
13:
14:function inverseOdd(value, modulus) {
15:  let a = value, b = modulus, x0 = 1, x1 = 0;
16:  while (b !== 0) {
17:    const q = Math.floor(a / b);
18:    [a, b] = [b, a - q * b];
19:    [x0, x1] = [x1, x0 - q * x1];
20:  }
21:  if (a !== 1) throw new Error(`nonunit pivot ${value} modulo ${modulus}`);
22:  return ((x0 % modulus) + modulus) % modulus;
23:}
24:
25:function leadingOdd(row) {
26:  let pivot = Infinity;
27:  for (const [column, value] of row) {
28:    if ((value & 1) && column < pivot) pivot = column;
29:  }
30:  return pivot;
31:}
32:
33:function cloneRow(row) {
34:  return new Map(row);
35:}
