37:function reduceAgainstPivots(row, pivots, modulus) {
38:  for (const [pivot, basis] of pivots) {
39:    const factor = row.get(pivot) || 0;
40:    if (!factor) continue;
41:    for (const [column, value] of basis) {
42:      let reduced = (row.get(column) || 0) - factor * value;
43:      reduced %= modulus;
44:      if (reduced < 0) reduced += modulus;
45:      if (reduced) row.set(column, reduced);
46:      else row.delete(column);
47:    }
48:  }
49:}
