51:function localLayer(rows, modulus) {
52:  const pivots = new Map();
53:  for (const source of rows) {
54:    const row = cloneRow(source);
55:    reduceAgainstPivots(row, pivots, modulus);
56:    const pivot = leadingOdd(row);
57:    if (pivot === Infinity) continue;
58:    const scale = inverseOdd(row.get(pivot), modulus);
59:    for (const [column, value] of row) {
60:      const normalized = (value * scale) % modulus;
61:      if (normalized) row.set(column, normalized);
62:      else row.delete(column);
63:    }
64:    pivots.set(pivot, row);
65:  }
66:
67:  const nextRows = [];
68:  let oddResidualRows = 0;
69:  for (const source of rows) {
70:    const row = cloneRow(source);
71:    reduceAgainstPivots(row, pivots, modulus);
72:    const divided = new Map();
73:    let hasOdd = false;
74:    for (const [column, value] of row) {
75:      if (value & 1) {
76:        hasOdd = true;
77:        break;
78:      }
79:      const next = value / 2;
80:      if (next) divided.set(column, next);
81:    }
82:    if (hasOdd) {
83:      oddResidualRows++;
84:      continue;
85:    }
86:    if (divided.size) nextRows.push(divided);
87:  }
88:  if (oddResidualRows) {
89:    throw new Error(`layer modulo ${modulus} left ${oddResidualRows} odd residual rows`);
90:  }
91:  return {pivots, nextRows};
92:}
